def sign(value):
    return 1 if value > 0 else -1


def folds(size, count):
    result = []
    for fold in range(count):
        training = [i for i in range(size) if i % count != fold]
        testing = [i for i in range(size) if i % count == fold]
        result.append((training, testing))
    return result


def correct_count(labels, values):
    return sum(sign(value) == label for label, value in zip(labels, values))


def binary_counts(labels, values):
    tp = fp = tn = fn = 0
    for label, value in zip(labels, values):
        prediction = sign(value)
        if label == 1:
            if prediction == 1:
                tp += 1
            else:
                fn += 1
        elif prediction == 1:
            fp += 1
        else:
            tn += 1
    return tp, fp, tn, fn


def auc(labels, values):
    positives = [i for i, label in enumerate(labels) if label == 1]
    negatives = [i for i, label in enumerate(labels) if label == -1]
    total = 0.0
    for positive in positives:
        for negative in negatives:
            if values[positive] > values[negative]:
                total += 1.0
            elif values[positive] == values[negative]:
                total += 0.5
    return total / (len(positives) * len(negatives))


def confusion_matrix(classes, predictions):
    matrix = [[0, 0, 0] for _ in range(3)]
    for actual, predicted in zip(classes, predictions):
        matrix[actual - 1][predicted - 1] += 1
    return matrix


def confusion_lines(matrix):
    lines = [" ".join(str(value) for value in row) for row in matrix]
    for index in range(3):
        column = sum(row[index] for row in matrix)
        row = sum(matrix[index])
        lines.append(
            f"class {index + 1} precision {ratio(matrix[index][index], column)} "
            f"recall {ratio(matrix[index][index], row)}"
        )
    return lines


def fixed(value, decimals=4):
    result = f"{value:.{decimals}f}"
    if result.startswith("-") and float(result) == 0:
        result = result[1:]
    return result


def ratio(numerator, denominator):
    return fixed(numerator / denominator) if denominator > 0 else "-"


def write_lines(path, lines):
    with open(path, "w", encoding="ascii", newline="\n") as destination:
        for line in lines:
            destination.write(line + "\n")

from math import exp

from evaluation import fixed


class Kernel:
    def __init__(self, name, kind, *arguments):
        self.name = name
        self.kind = kind
        if kind == "poly":
            self.degree = int(arguments[0])
            self.gamma = float(arguments[1])
            self.coef0 = float(arguments[2])
        elif kind == "rbf":
            self.gamma = float(arguments[0])

    def value(self, first, second):
        if self.kind == "rbf":
            e1 = first[0] - second[0]
            e2 = first[1] - second[1]
            return exp(-self.gamma * (e1 * e1 + e2 * e2))
        dot = first[0] * second[0] + first[1] * second[1]
        if self.kind == "linear":
            return dot
        factor = self.gamma * dot + self.coef0
        value = 1.0
        for _ in range(self.degree):
            value *= factor
        return value

    def description(self):
        if self.kind == "linear":
            return "linear"
        if self.kind == "rbf":
            return f"rbf gamma {fixed(self.gamma)}"
        return (
            f"poly degree {self.degree} gamma {fixed(self.gamma)} "
            f"coef0 {fixed(self.coef0)}"
        )

    def matrix(self, points):
        return [[self.value(first, second) for second in points] for first in points]


def submatrix(matrix, indices):
    return [[matrix[i][j] for j in indices] for i in indices]

class Model:
    def __init__(self, points, labels, kernel, matrix, coefficient, settings):
        self.points = points
        self.labels = labels
        self.kernel = kernel
        self.matrix = matrix
        self.C = coefficient
        self.tolerance = settings.tolerance
        self.eps = settings.eps
        self.max_passes = settings.max_passes
        self.alpha = [0.0] * len(points)
        self.b = 0.0
        self.errors = [-float(label) for label in labels]
        self.full_passes = 0
        self.nonbound_passes = 0
        self.examined = 0
        self.steps = 0
        self.choices = {"heuristic": 0, "nonbound_loop": 0, "full_loop": 0}
        self.clipping = {"none": 0, "lower": 0, "upper": 0}
        self.records = []
        self.converged = False

    @property
    def passes(self):
        return self.full_passes + self.nonbound_passes

    def nonbound(self, index):
        return 0 < self.alpha[index] < self.C

    def snap(self, value):
        if value < 0.00000001:
            return 0.0
        if value > self.C - 0.00000001:
            return self.C
        return value

    def take(self, first, second):
        if first == second:
            return False
        alpha1, alpha2 = self.alpha[first], self.alpha[second]
        y1, y2 = self.labels[first], self.labels[second]
        error1, error2 = self.errors[first], self.errors[second]
        if y1 != y2:
            lower = max(0.0, alpha2 - alpha1)
            upper = min(self.C, self.C + alpha2 - alpha1)
        else:
            lower = max(0.0, alpha2 + alpha1 - self.C)
            upper = min(self.C, alpha2 + alpha1)
        if lower == upper:
            return False
        k11 = self.matrix[first][first]
        k12 = self.matrix[first][second]
        k22 = self.matrix[second][second]
        eta = k11 + k22 - 2 * k12
        if eta <= 0:
            return False
        a2 = alpha2 + y2 * (error1 - error2) / eta
        clipping = "none"
        if a2 < lower:
            a2 = lower
            clipping = "lower"
        elif a2 > upper:
            a2 = upper
            clipping = "upper"
        a2 = self.snap(a2)
        if abs(a2 - alpha2) < self.eps * (a2 + alpha2 + self.eps):
            return False
        a1 = self.snap(alpha1 + y1 * y2 * (alpha2 - a2))
        t1 = y1 * (a1 - alpha1)
        t2 = y2 * (a2 - alpha2)
        b1 = error1 + t1 * k11 + t2 * k12 + self.b
        b2 = error2 + t1 * k12 + t2 * k22 + self.b
        if 0 < a1 < self.C:
            threshold = b1
        elif 0 < a2 < self.C:
            threshold = b2
        else:
            threshold = (b1 + b2) / 2
        delta = threshold - self.b
        for index in range(len(self.points)):
            self.errors[index] = self.errors[index] + (
                t1 * self.matrix[first][index] + t2 * self.matrix[second][index] - delta
            )
        if 0 < a1 < self.C:
            self.errors[first] = 0.0
        if 0 < a2 < self.C:
            self.errors[second] = 0.0
        self.alpha[first], self.alpha[second] = a1, a2
        self.b = threshold
        self.steps += 1
        self.clipping[clipping] += 1
        return True

    def examine(self, second):
        self.examined += 1
        residual = self.errors[second] * self.labels[second]
        violates = (
            residual < -self.tolerance and self.alpha[second] < self.C
        ) or (residual > self.tolerance and self.alpha[second] > 0)
        if not violates:
            return 0
        partner = None
        largest_difference = -1.0
        for index in range(len(self.points)):
            if index != second and self.nonbound(index):
                difference = abs(self.errors[index] - self.errors[second])
                if difference > largest_difference:
                    largest_difference = difference
                    partner = index
        if partner is not None and self.take(partner, second):
            self.choices["heuristic"] += 1
            return 1
        for first in range(len(self.points)):
            if self.nonbound(first) and self.take(first, second):
                self.choices["nonbound_loop"] += 1
                return 1
        for first in range(len(self.points)):
            if self.take(first, second):
                self.choices["full_loop"] += 1
                return 1
        return 0

    def fit(self):
        examine_all = True
        while True:
            examined_before = self.examined
            changed = 0
            for index in range(len(self.points)):
                if examine_all or self.nonbound(index):
                    changed += self.examine(index)
            if examine_all:
                self.full_passes += 1
            else:
                self.nonbound_passes += 1
            record = {
                "full": examine_all,
                "examined": self.examined - examined_before,
                "changed": changed,
            }
            if examine_all:
                record["alpha"] = self.alpha[:]
            self.records.append(record)
            if examine_all and changed == 0:
                self.converged = True
                break
            if self.passes == self.max_passes:
                break
            if examine_all:
                examine_all = False
            elif changed == 0:
                examine_all = True
        return self

    def decision(self, point):
        total = 0.0
        for index, alpha in enumerate(self.alpha):
            if alpha > 0:
                total += alpha * self.labels[index] * self.kernel.value(self.points[index], point)
        return total - self.b

    def training_decisions(self):
        values = []
        for row in self.matrix:
            total = 0.0
            for index, alpha in enumerate(self.alpha):
                if alpha > 0:
                    total += alpha * self.labels[index] * row[index]
            values.append(total - self.b)
        return values


def train(points, labels, kernel, matrix, coefficient, settings):
    return Model(points, labels, kernel, matrix, coefficient, settings).fit()
